    objs.append(make_mesh_object("EXTERIOR_Rear_Adventure_Bumper", bm_rbumper, mats['cladding_dark']))

    # Aerodynamic Side Mirrors with Integrated Turn Signal Slits
    bm_mirrors = bmesh.new()
